SourceCode.Declaration:
abstract class METTMSEngineHeaderContract 
{   
    METTMSSourceRecordHeaderMap sourceRecord;
    Common extensionTable;
    TMSCarrierCode carrierCode;
    METOrderSplitGroup splitGroup;
    str shipmentId;
    boolean execOrder = false;
    METTMSShipmentID shipmentRecordId;
    METRouteStopNum routeStop;
    METWMSPicklistNumber picklistNumber;
    METTMSSourceRecordHeaderExtMap headerExtMap;

}

Method.Source:
/// <summary>
/// Construct and initialized a new instance of class <c>METTMSEngineHeaderContract</c>
/// </summary>
/// <param name = "_sourceDocumentType">Source document type enum value</param>
/// <param name = "_sourceRecord">Source document record buffer</param>
/// <param name = "_shipmentId">Shipment Id (optional)</param>
/// <param name = "_wmsPickinglistNumber">Picking list number optional</param>
/// <returns></returns>
public static METTMSEngineHeaderContract construct(METTMSSourceDocumentType _sourceDocumentType, METTMSSourceRecordHeaderMap _sourceRecord, METTMSShipmentID _shipmentId = "", METWMSPicklistNumber _wmsPickinglistNumber = "")
{
    METTMSEngineDocumentTypeAttribute attribute = new METTMSEngineDocumentTypeAttribute(_sourceDocumentType);

    METTMSEngineHeaderContract contract = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(METTMSEngineHeaderContract), attribute);

    contract.sourceRecord = _sourceRecord;
    contract.shipmentRecordId = _shipmentId;
    contract.picklistNumber = _wmsPickinglistNumber;

    contract.init();

    return contract;
}

/// <summary>
/// Gets the staging lane id of the document
/// </summary>
/// <returns>Staging lane Id</returns>
public METStagingLaneId getStagingLaneId()
{
    METStagingLaneId ret = headerExtMap.StagingLaneId;

    return ret;
}

/// <summary>
/// Shipment Id
/// </summary>
/// <param name = "_shipmentRecordId">Shipment Id to be set</param>
/// <returns>Shipment Id attached to this instance</returns>
public METTMSShipmentID parmShipmentRecordId(METTMSShipmentID _shipmentRecordId = shipmentRecordId)
{
    shipmentRecordId = _shipmentRecordId;

    return shipmentRecordId;
}

/// <summary>
/// Initializes the contract members
/// </summary>
abstract void init()
{

}

/// <summary>
/// Is this an internal crossdock order. Implemented in child classes.
/// </summary>
/// <returns>Yes, if this is a cross dock order, otherwise No</returns>
public NoYes isInternalCrossDockOrder()
{
    return NoYes::No;
}

/// <summary>
/// Source document record buffer map.
/// </summary>
/// <param name = "_sourceRecord">Source document header map</param>
/// <returns>Initialized source document header map</returns>
public METTMSSourceRecordHeaderMap parmSourceRecord(METTMSSourceRecordHeaderMap _sourceRecord = sourceRecord)
{
    sourceRecord = _sourceRecord;

    return sourceRecord;
}

/// <summary>
/// Gets the order split group from source document
/// </summary>
/// <returns>Order split group id</returns>
public METOrderSplitGroup getOrderSplitGroup()
{
    return headerExtMap.OrderSplitGroup;
}

/// <summary>
/// Gets the route stop identifier from source document
/// </summary>
/// <returns>Route stop identifier</returns>
public METRouteStopIdentifier getRouteStopIdentifier()
{
    METRouteStopIdentifier ret = headerExtMap.RouteStopIdentifier;

    return ret;
}

/// <summary>
/// Get the route identifier of the order
/// </summary>
/// <returns>Route identifier</returns>
public METRouteIdentifier getRouteIdentifier()
{
    METRouteIdentifier ret = headerExtMap.RouteIdentifier;

    return ret;
}

/// <summary>
/// Returns the carried code of the order
/// </summary>
public TMSCarrierCode getCarrierCode()
{
    return carrierCode;
}

/// <summary>
/// Gets the customer account of the order
/// </summary>
/// <returns>Customer account number</returns>
abstract CustAccount getCustomerAccount()
{

}

/// <summary>
/// Returns the extension tables
/// </summary>
/// <returns>Buffer of source document extension table</returns>
abstract Common getExtensionTable()
{

}

/// <summary>
/// Shipment Id
/// </summary>
/// <returns>Shipment Id</returns>
public METTMSShipmentID getShipmentID()
{
    return shipmentId;
}

/// <summary>
/// Retrive the route id of the order and return it
/// </summary>
/// <returns>Route Id</returns>
abstract METRoute getRoute()
{

}

/// <summary>
/// Get success or failure message
/// </summary>
/// <param name = "_shipmentCreated">Is shipment created</param>
/// <returns>Success or failure message</returns>
abstract SysInfoLogStr showInfo(boolean _shipmentCreated)
{
}

/// <summary>
/// Validate if Sales order excluded from TMS engine
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
abstract boolean isOrderExcluded()
{

}

/// <summary>
/// Gets the shipping date of the order, if the Confirmed ship date is not available then returns the requested ship date of the sales order.
/// </summary>
public TransDate getShipDate()
{
    return sourceRecord.ConfirmedShipDate;
}

/// <summary>
/// Confirmed receipt date of the order
/// </summary>
/// <returns>Receipt date</returns>
public TransDate getReceiptDate()
{
    return sourceRecord.ConfirmedReceiptDate;
}

/// <summary>
/// Get the destination type of the shipment.
/// </summary>
/// <returns>Customer if this a sales, otherwise warehouse</returns>
abstract METDestinationType getDestinationType()
{

}

/// <summary>
/// Gets the route stop number of the order
/// </summary>
/// <returns>Route stop number</returns>
abstract METRouteStopNum getRouteStop()
{

}
